import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cstdint>

namespace {

constexpr int TILE = 32;

__global__ void matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M,
    int K,
    int N
) {
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    const int tid = threadIdx.x;
    const int warp_id = tid >> 5;
    const int lane = tid & 31;
    const int warp_row = warp_id >> 1;
    const int warp_col = warp_id & 1;

    const int row_base = blockIdx.y * TILE + warp_row * 16 + (lane & 7) * 2;
    const int col_base = blockIdx.x * TILE + warp_col * 16 + (lane >> 3) * 4;

    float acc[2][4];
    #pragma unroll
    for (int r = 0; r < 2; ++r) {
        #pragma unroll
        for (int q = 0; q < 4; ++q) {
            acc[r][q] = 0.0f;
        }
    }

    const int tiles = (K + TILE - 1) / TILE;
    for (int tile = 0; tile < tiles; ++tile) {
        for (int idx = tid; idx < TILE * TILE; idx += 128) {
            const int smem_row = idx / TILE;
            const int smem_col = idx - smem_row * TILE;

            const int a_row = blockIdx.y * TILE + smem_row;
            const int a_col = tile * TILE + smem_col;
            As[smem_row][smem_col] =
                (a_row < M && a_col < K) ? A[a_row * K + a_col] : 0.0f;

            const int b_row = tile * TILE + smem_row;
            const int b_col = blockIdx.x * TILE + smem_col;
            Bs[smem_row][smem_col] =
                (b_row < K && b_col < N) ? B[b_row * N + b_col] : 0.0f;
        }

        __syncthreads();

        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            const float a0 = As[warp_row * 16 + (lane & 7) * 2 + 0][k];
            const float a1 = As[warp_row * 16 + (lane & 7) * 2 + 1][k];

            #pragma unroll
            for (int q = 0; q < 4; ++q) {
                const float b = Bs[k][warp_col * 16 + (lane >> 3) * 4 + q];
                acc[0][q] = fmaf(a0, b, acc[0][q]);
                acc[1][q] = fmaf(a1, b, acc[1][q]);
            }
        }

        __syncthreads();
    }

    #pragma unroll
    for (int r = 0; r < 2; ++r) {
        const int row = row_base + r;
        if (row < M) {
            #pragma unroll
            for (int q = 0; q < 4; ++q) {
                const int col = col_base + q;
                if (col < N) {
                    C[row * N + col] = acc[r][q];
                }
            }
        }
    }
}

} // namespace

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.scalar_type() == torch::kFloat32, "B must be float32");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D tensors");
    TORCH_CHECK(A.size(1) == B.size(0), "Incompatible matrix dimensions");

    auto A_contig = A.contiguous();
    auto B_contig = B.contiguous();

    const int M = static_cast<int>(A_contig.size(0));
    const int K = static_cast<int>(A_contig.size(1));
    const int N = static_cast<int>(B_contig.size(1));

    auto C = torch::empty({M, N}, A_contig.options());

    const dim3 block(128);
    const dim3 grid(
        (N + TILE - 1) / TILE,
        (M + TILE - 1) / TILE
    );

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    matmul_kernel<<<grid, block, 0, stream>>>(
        A_contig.data_ptr<float>(),
        B_contig.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        K,
        N
    );

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return C;
}
"""

_cpp_src = r"""
#include <torch/extension.h>

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

_matmul_ext = load_inline(
    name="custom_cuda_matmul_extension",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["matmul_cuda"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    extra_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return _matmul_ext.matmul_cuda(A, B)

